public class GameAutoStartAudit extends Instrumentation {
 int checks;public void onCreate(Bundle b){super.onCreate(b);start();}void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
 Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}Object call(Object o,String n,Class<?>[] ts,Object...a)throws Exception{Method m=o.getClass().getDeclaredMethod(n,ts);m.setAccessible(true);return m.invoke(o,a);}
 AccessibilityNodeInfo find(AccessibilityNodeInfo n,String text){if(n==null)return null;if(n.getText()!=null&&n.getText().toString().equalsIgnoreCase(text))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo result=find(n.getChild(i),text);if(result!=null)return result;}return null;}
 boolean click(String...texts){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root==null)return false;for(String text:texts){AccessibilityNodeInfo n=find(root,text);if(n==null)continue;android.graphics.Rect at=new android.graphics.Rect();n.getBoundsInScreen(at);long now=SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(now,now,0,at.centerX(),at.centerY(),0),up=android.view.MotionEvent.obtain(now,now+80,1,at.centerX(),at.centerY(),0);down.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);up.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(down,true);getUiAutomation().injectInputEvent(up,true);down.recycle();up.recycle();return true;}return false;}
 String labels(AccessibilityNodeInfo n){if(n==null)return "";String out=n.getText()==null?"":n.getText()+"|";for(int i=0;i<n.getChildCount();i++)out+=labels(n.getChild(i));return out;}
 boolean waitClick(String...text)throws Exception{for(int i=0;i<50;i++){if(click(text))return true;Thread.sleep(100);}return false;}
 public void onStart(){Bundle result=new Bundle();Activity live=null;try{getTargetContext().stopService(new Intent().setClassName("app.kinnect.live","app.kinnect.live.KinnectService"));Class<?> apiType=getTargetContext().getClassLoader().loadClass("app.kinnect.live.NativeApi");Object api=apiType.getField("shared").get(null);call(api,"configure",new Class[]{String.class},"https://127.0.0.1:9");live=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.LiveActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(500);final Activity a=live;runOnMainSync(()->{try{Object socket=get(a,"socket");if(socket!=null)call(socket,"close",new Class[]{});set(a,"socket",null);set(a,"config",new JSONObject().put("iceServers",new JSONArray()));set(a,"ready",true);set(a,"liveMode","game");set(a,"gameComments",false);set(a,"cameraSetup",true);set(a,"gameTitle","Minecraft");call(a,"requestGameProjection",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(800);
  // Exercise the real OS consent dialog, never inject a MediaProjection token.
  check(!(Boolean)get(a,"gameSession"),"Session started before Android consent");check(waitClick("Start now","Start sharing","Share screen","Bắt đầu ngay","Bắt đầu"),"Consent button missing: "+labels(getUiAutomation().getRootInActiveWindow()));
  for(int i=0;i<60&&!(Boolean)get(a,"gameSession");i++)Thread.sleep(100);waitForIdleSync();Thread.sleep(300);check((Boolean)get(a,"gameSession"),"Foreground projection session not started");Object rtc=get(a,"rtc");check(rtc!=null,"Screen RTC missing");check(get(rtc,"local")==null&&get(a,"localLive")==null,"Screen capture must not have a local preview sink");Object capture=get(rtc,"camera");Thread.sleep(1000);check((Long)capture.getClass().getMethod("getNumCapturedFrames").invoke(capture)>0,"No actual screen frames");check(!(Boolean)get(a,"joined"),"Offline audit must not create a real Live");
  runOnMainSync(()->{try{set(a,"host",true);call(a,"event",new Class[]{JSONObject.class},new JSONObject().put("type","joined").put("multiGuest",true).put("room",new JSONObject().put("id","offline-qa").put("liveMode","game").put("gameTitle","Minecraft")));}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(2000);check(!a.isFinishing(),"Opening game terminated Live");check("app.kinnect.audit".contentEquals(getUiAutomation().getRootInActiveWindow().getPackageName()),"Joined acknowledgement did not auto-open game");check(get(a,"socket")==null,"No public server connection expected");Object mix=call(rtc,"audioMix",new Class[]{});set(mix,"mic",false);ByteBuffer pcm=ByteBuffer.allocateDirect(960).order(ByteOrder.LITTLE_ENDIAN);call(mix,"mix",new Class[]{ByteBuffer.class,int.class,int.class,int.class,int.class,long.class},pcm,2,1,48000,960,1L);long energy=0;for(int i=0;i<480;i++)energy+=Math.abs(pcm.getShort(i*2));check(energy/480>1000,"Separate-UID game audio was not captured: "+energy/480);
  Object service=get(a,"gameService");runOnMainSync(()->{try{call(a,"toggleScreenPause",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});check((Boolean)get(a,"screenPaused"),"Pause flag missing");check(!(Boolean)get(mix,"gameEnabled"),"Game sound not muted during privacy pause");Object video=get(rtc,"video");check(!(Boolean)video.getClass().getMethod("enabled").invoke(video),"Screen video still enabled during pause");
  runOnMainSync(()->{try{call(a,"toggleScreenPause",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});check(!(Boolean)get(a,"screenPaused"),"Resume failed");
  // Returning to Kinnect must mask outgoing video/audio, without feeding captured frames into itself.
  getTargetContext().startActivity(new Intent().setClassName("app.kinnect.live","app.kinnect.live.LiveActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP));Thread.sleep(700);check((Boolean)get(a,"gameControllerVisible"),"Controller visibility not tracked");check(!(Boolean)video.getClass().getMethod("enabled").invoke(video),"Controller screen broadcast to viewers");check(!(Boolean)get(mix,"gameEnabled"),"Game audio must hold while controller visible");check(get(a,"localLive")==null,"Local screen renderer reattached");try(java.io.FileOutputStream file=new java.io.FileOutputStream(new java.io.File(a.getExternalFilesDir(null),"game36-controller.png"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,file);}runOnMainSync(()->{try{call(a,"openGameApp",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});for(int n=0;n<50&&(Boolean)get(a,"gameControllerVisible");n++)Thread.sleep(100);check(!(Boolean)get(a,"gameControllerVisible"),"Game did not resume foreground; session="+get(a,"gameSession"));check((Boolean)video.getClass().getMethod("enabled").invoke(video),"Screen did not resume for game");check((Boolean)get(mix,"gameEnabled"),"Game audio did not resume");
  // Revocation ends the session and service instead of emitting a frozen screen forever.
  Object projection=capture.getClass().getMethod("getMediaProjection").invoke(capture);projection.getClass().getMethod("stop").invoke(projection);for(int i=0;i<50&&!a.isFinishing();i++)Thread.sleep(100);check(!(Boolean)get(a,"gameSession"),"OS revocation did not release session");check(get(a,"gameService")==null,"Foreground service leaked");check(a.isFinishing(),"Room did not close on screen revocation");
  result.putString("result","PASS "+checks+": new setup default-display consent, simulated local joined acknowledgement auto-launch, foreground service, actual screen frames, separate-UID synthetic game audio capture/mix, background survival, privacy pause/resume and OS revocation cleanup. No server room created. No self preview; controller visibility holds and game resume verified.");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{final Activity a=live;if(a!=null)runOnMainSync(()->a.finish());}}
}
